// Make jumping feel forgiving when the button press is slightly early or slightly late.
// jump-controller: original MIT-licensed native educational port.
// Generated by tools/ports/generate.py; edit the specification to preserve parity.
// Input: [coyote_seconds, buffer_seconds, ...[time,grounded_flag,pressed_flag]]
// Output: [...jump_flags]
// Monotonic finite timestamps. One consumed jump per grounded episode; collision reporting is the
// caller responsibility.
// Precondition: finite, correctly shaped data; integer indices/counts/IDs.
// See ../PORTS.md for examples, limits, and the shared test fixtures.

#include "mechanic.h"
#include <assert.h>
#include <math.h>
// Count how many numbers are in this list.
static inline double port_length(const PortVector *a) { return (double)a->count; }
// Check that a position is a whole number inside the list before using it.
static inline size_t port_index(const PortVector *a, double i) { assert(isfinite(i) && i>=0 && i<(double)a->count && floor(i)==i); return (size_t)i; }
// Read one number at a zero-based position; stop if that position does not exist.
static inline double port_get(const PortVector *a, double i) { return a->values[port_index(a,i)]; }
// Add one number to the end of the list.
static inline void port_push(PortVector *a, double v) { assert(a->count<PORT_CAPACITY); a->values[a->count++]=v; }

// 1. Remember the last time the character touched the ground.
// 2. Remember the last time the jump button was pressed.
// 3. Allow a jump if those memories are still recent enough.
// 4. Use up that jump so one press cannot keep creating jumps in mid-air. A new landing restores
// it.
PortVector game_jump_controller_compute(PortVector data) {
    double coyote = 0;
    double buffer = 0;
    double last_ground = 0;
    double last_press = 0;
    double previous_time = 0;
    double used = 0;
    double was_grounded = 0;
    PortVector result = {0};
    double i = 0;
    double now = 0;
    double grounded = 0;
    double pressed = 0;
    double jump = 0;
    coyote = port_get(&data, 0.0);
    buffer = port_get(&data, 1.0);
    if (((coyote < 0.0) || (buffer < 0.0))) {
        return (PortVector){.values={-(1.0)}, .count=1};
    }
    last_ground = -(1e+30);
    last_press = -(1e+30);
    previous_time = -(1e+30);
    used = 0.0;
    was_grounded = 0.0;
    result = (PortVector){.values={0}, .count=0};
    i = 2.0;
    while ((i < port_length(&data))) {
        now = port_get(&data, i);
        grounded = port_get(&data, (i + 1.0));
        pressed = port_get(&data, (i + 2.0));
        if ((now < previous_time)) {
            return (PortVector){.values={-(1.0)}, .count=1};
        }
        previous_time = now;
        if ((grounded == 1.0)) {
            if ((was_grounded == 0.0)) {
                used = 0.0;
            }
            last_ground = now;
        }
        was_grounded = grounded;
        if ((pressed == 1.0)) {
            last_press = now;
        }
        jump = 0.0;
        if (((used == 0.0) && ((now - last_ground) <= coyote) && ((now - last_press) <= buffer))) {
            used = 1.0;
            last_press = -(1e+30);
            jump = 1.0;
        }
        port_push(&result, jump);
        i += 3.0;
    }
    return result;
}
